window.futvizVista("eficiencia-definicion","<div class=\"rx-mount\" data-rx=\"scatter\" data-rx-id=\"eficiencia-definicion\" style=\"min-height:520px\"></div><script>(window.futvizVistas=window.futvizVistas||{})[\"eficiencia-definicion\"]={\"id\":\"eficiencia-definicion\",\"titulo\":\"Eficiencia de definici\u00f3n\",\"bajada\":\"Cada punto es un equipo. A la derecha, mayor % de tiros a puerta; arriba, m\u00e1s goles por cada tiro a puerta.\",\"pregunta\":\"\u00bfQu\u00e9 equipo aprovecha mejor sus ocasiones?\",\"tabla\":\"equipos\",\"entidad\":\"equipos\",\"x\":{\"col\":\"sh_Standard_SoT%\",\"label\":\"Precisi\u00f3n \u2014 % de tiros que van a puerta (SoT%)\",\"corto\":\"Precisi\u00f3n\",\"dec\":1},\"y\":{\"col\":\"sh_Standard_G/SoT\",\"label\":\"Definici\u00f3n \u2014 goles por tiro a puerta (G/SoT)\",\"corto\":\"Definici\u00f3n\",\"dec\":2},\"referencia\":{\"tipo\":\"promedios\",\"cuadrantes\":{\"tr\":\"certeros y letales\",\"tl\":\"poco a puerta, letales\",\"br\":\"a puerta, sin pegada\",\"bl\":\"ni certeros ni letales\"}},\"requiere\":[\"sh_Standard_SoT%\",\"sh_Standard_G/SoT\"],\"subtitulo\":\"Equipos de las 5 ligas \u00b7 {temporada}\",\"filtros\":{\"nivel\":true},\"metricas\":[{\"id\":\"dist\",\"etiqueta\":\"M\u00e1s at\u00edpicos\",\"ayuda\":\"Los que m\u00e1s se alejan del grupo, para bien o para mal\"},{\"id\":\"x\",\"etiqueta\":\"Precisi\u00f3n\",\"ayuda\":\"Ordenados por Precisi\u00f3n \u2014 % de tiros que van a puerta (SoT%)\"},{\"id\":\"y\",\"etiqueta\":\"Definici\u00f3n\",\"ayuda\":\"Ordenados por Definici\u00f3n \u2014 goles por tiro a puerta (G/SoT)\"}],\"queMirar\":\"Arriba a la derecha est\u00e1n los que hacen bien las dos cosas; abajo a la derecha, los que llevan a puerta buena parte de sus tiros y marcan poco de ellos.\",\"porQue\":\"Las dos van en ejes separados porque **no son la misma habilidad**: correlacionan 0.31 sobre las 580 observaciones, o sea que comparten apenas un 10% de su variaci\u00f3n. Un equipo puede ser muy bueno generando remates claros y flojo remat\u00e1ndolos, y al rev\u00e9s. Si se mezclaran en un solo indicador de \\\"eficiencia\\\" esa distinci\u00f3n se perder\u00eda, que es justo lo que el gr\u00e1fico quiere mostrar.\",\"insight\":\"definicion\",\"fuente\":\"FBref\",\"colorPor\":[\"liga\"]};</script>");